#include <vector>

class Solution {
public:
    int countMirrorPaths(std::vector<std::vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        int MOD = 1000000007;
        std::vector<std::vector<int>> dp(m, std::vector<int>(n, 0));
        if (grid[0][0] == 0) dp[0][0] = 1;

        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (grid[r][c] != 0 || dp[r][c] == 0) continue;
                if (r + 1 < m && grid[r + 1][c] == 0) {
                    dp[r + 1][c] = (dp[r + 1][c] + dp[r][c]) % MOD;
                }
                if (c + 1 < n && grid[r][c + 1] == 0) {
                    dp[r][c + 1] = (dp[r][c + 1] + dp[r][c]) % MOD;
                }
            }
        }
        return dp[m - 1][n - 1];
    }
};

