var countMirrorPaths = function(grid) {
    const m = grid.length, n = grid[0].length;
    const MOD = 1000000007;
    const dp = Array.from({ length: m }, () => new Int32Array(n));
    if (grid[0][0] === 0) dp[0][0] = 1;

    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (grid[r][c] !== 0 || dp[r][c] === 0) continue;
            if (r + 1 < m && grid[r + 1][c] === 0) {
                dp[r + 1][c] = (dp[r + 1][c] + dp[r][c]) % MOD;
            }
            if (c + 1 < n && grid[r][c + 1] === 0) {
                dp[r][c + 1] = (dp[r][c + 1] + dp[r][c]) % MOD;
            }
        }
    }
    return dp[m - 1][n - 1];
};
